pub(crate) fn format_path_display_into_scratch(&self, path: &[u8]) {
    let mut buf = self.scratch.borrow_mut();
    buf.clear();
    if path.is_empty() {
        buf.extend_from_slice(b"<stdin>");
        return;
    }
    for (i, &b) in path.iter().enumerate() {
        if b == b'\\' || b == b'/' {
            buf.push(b'/');
            continue;
        }
        if b >= 0x20 && b <= 0x7E && b != b'"' {
            buf.push(b);
            continue;
        }
        if i + 1 < path.len() && Self::is_utf8_cont(path[i + 1]) && b >= 0xC2 {
            buf.push(b);
            continue;
        }
        buf.push(b);
    }
}

pub(crate) fn format_duration_into_scratch(&self, duration: time::Duration) {
    let mut buf = self.scratch.borrow_mut();
    buf.clear();
    let secs = duration.as_secs();
    let nanos = duration.subsec_nanos();
    Self::push_decimal(&mut buf, secs);
    buf.push(b'.');
    let mut frac = nanos / 1000;
    let mut tmp = [0u8; 6];
    for i in 0..6 {
        tmp[5 - i] = b'0' + (frac % 10) as u8;
        frac /= 10;
    }
    buf.extend_from_slice(&tmp);
    buf.push(b's');
}

