pub(crate) fn format_omitted_into_scratch(
    &self,
    kind: u8,
    match_count: usize,
    remaining: usize,
) {
    let mut buf = self.scratch.borrow_mut();
    buf.clear();
    if kind == 0 {
        buf.extend_from_slice(b"[... omitted end of long line]");
    } else if kind == 1 {
        buf.extend_from_slice(b" [... ");
        Self::push_decimal(&mut buf, remaining as u64);
